shell_commands:
/bin/zsh -lc "cat > src/orchestration/tools/registry.passthrough.test.ts <<'EOF'
import {jest} from '@jest/globals';
import {ToolRegistry} from './registry.js';

// specs/hal-engine-tool-input-validation/spec.md#5
it('passes valid input and extra properties through unchanged', async () => {
  const registry = new ToolRegistry();
  const execute = jest.fn(async () => 'sunny');
  registry.register(
    {name: 'weather', description: 'Weather', inputSchema: {type: 'object', properties: {location: {type: 'string'}}, required: ['location']}},
    execute
  );
  const input = {location: 'Berlin', extra: 'kept'};
  await registry.execute('weather', input);
  expect(execute).toHaveBeenCalledTimes(1);
  expect(execute).toHaveBeenCalledWith(input, undefined);
});
EOF
 timeout 300 npm test -- --runTestsByPath src/orchestration/tools/registry.passthrough.test.ts --runInBand"

/bin/zsh -lc "cat > src/orchestration/tools/registry.passthrough.test.ts <<'EOF'
import {ToolRegistry} from './registry.js';

// specs/hal-engine-tool-input-validation/spec.md#3
it('identifies the full path of a missing nested property', async () => {
  const registry = new ToolRegistry();
  registry.register(
    {name: 'weather', description: 'Weather', inputSchema: {type: 'object', properties: {address: {type: 'object', required: ['location']}}}},
    async () => 'sunny'
  );
  const response = await registry.execute('weather', {address: {}});
  expect(response.result).toContain('/address/location');
});
EOF
 timeout 300 npm test -- --runTestsByPath src/orchestration/tools/registry.passthrough.test.ts --runInBand"
